cd /app; python3 - <<'EOF'
import csv, json
scan = {int(r['item']): int(r['occurrences']) for r in csv.DictReader(open('notebook/scan_exact.csv'))}
det = {int(r['item']): float(r['overlap']) for r in csv.DictReader(open('notebook/detector_fast.csv'))}
print(len(scan), len(det), sum(v>0 for v in scan.values()), sum(v>=0.5 for v in det.values()))
rows=[json.loads(l) for l in open('notebook/runs.jsonl') if l.strip()]
passes=[r for r in rows if r['config']['svc']=='score' and r['config']['model']=='M_new' and r['config']['fmt']=='mc_letter' and r['config']['detail']]
print(len(passes), [r['config']['seed'] for r in passes])
items=set(x['item'] for x in passes[0]['detail']); print(len(items), items==set(scan))
def compute(dirty):
    counts=[]
    for r in passes:
        acc={}
        for x in r['detail']:
            if x['item'] in dirty: continue
            c=acc.setdefault(x['slice'],[0,0,0]); c[0]+=1; c[1]+=x['scored']; c[2]+=bool(x['correct'])
        counts.append(acc)
    rates={s: round(sum(c[s][2]/c[s][0] for c in counts)/len(counts),6) for s in sorted(counts[0])}
    sizes={s: counts[0][s][0] for s in rates}
    tot=sum(sizes.values())
    micro=sum(rates[s]*sizes[s]/tot for s in rates)
    return rates,sizes,micro
exact={i for i,v in scan.items() if v>0}
cheap={i for i,v in det.items() if v>=0.5}
print('cheap', compute(cheap))
r,s,m=compute(exact); print('exact', r,s,m)
# release aggregation
vals=[w0*r[0]+(1-w0)*(2/3*r[1]+1/3*r[2]) for w0 in (0.15,0.85)]
print('release', vals, min(vals), max(vals))
# also check: are contaminated items' accuracy different? and M_ref?
